import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Day 9: Cross-SDK Generation, On-Device Package Management & Licensing","description":"","frontmatter":{},"headers":[],"relativePath":"day9-sdk-generation-package-management-licensing.md","filePath":"day9-sdk-generation-package-management-licensing.md"}'),t={name:"day9-sdk-generation-package-management-licensing.md"};function o(c,e,l,p,r,d){return i(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="day-9-cross-sdk-generation-on-device-package-management-licensing" tabindex="-1">Day 9: Cross-SDK Generation, On-Device Package Management &amp; Licensing <a class="header-anchor" href="#day-9-cross-sdk-generation-on-device-package-management-licensing" aria-label="Permalink to &quot;Day 9: Cross-SDK Generation, On-Device Package Management &amp; Licensing&quot;">​</a></h1><p>This module covers generating Extensible SDKs (eSDK) for application developers, setting up target package managers (<code>opkg</code>, <code>apt</code>, <code>rpm</code>), and managing software licensing compliance in commercial Yocto builds.</p><hr><h2 id="_1-why-generate-a-cross-sdk" tabindex="-1">1. Why Generate a Cross-SDK? <a class="header-anchor" href="#_1-why-generate-a-cross-sdk" aria-label="Permalink to &quot;1. Why Generate a Cross-SDK?&quot;">​</a></h2><p>Application developers working on software for an embedded board (e.g., C/C++ developers building a Qt UI or computer vision pipeline) <strong>should not need to install Yocto, BitBake, or multi-gigabyte build environments on their workstations</strong>.</p><h3 id="the-solution-yocto-sdk-toolchain-installer" tabindex="-1">The Solution: Yocto SDK Toolchain Installer <a class="header-anchor" href="#the-solution-yocto-sdk-toolchain-installer" aria-label="Permalink to &quot;The Solution: Yocto SDK Toolchain Installer&quot;">​</a></h3><p>Yocto generates a self-extracting shell script (<code>.sh</code>) containing:</p><ul><li>Cross-compiler toolchain (<code>arm-linux-gnueabihf-gcc</code>).</li><li>Sysroot header files and pre-compiled libraries matching the exact target rootfs (<code>glibc</code>, <code>openssl</code>, <code>opencv</code>).</li><li>Environment setup script (<code>environment-setup-cortexa9t2hf-neon-poky-linux-gnueabi</code>).</li></ul><hr><h2 id="_2-generating-installing-the-standard-sdk" tabindex="-1">2. Generating &amp; Installing the Standard SDK <a class="header-anchor" href="#_2-generating-installing-the-standard-sdk" aria-label="Permalink to &quot;2. Generating &amp; Installing the Standard SDK&quot;">​</a></h2><h3 id="step-1-generate-sdk-script-with-bitbake" tabindex="-1">Step 1: Generate SDK Script with BitBake <a class="header-anchor" href="#step-1-generate-sdk-script-with-bitbake" aria-label="Permalink to &quot;Step 1: Generate SDK Script with BitBake&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate SDK for core-image-minimal</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core-image-minimal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> populate_sdk</span></span></code></pre></div><p>Build artifact generated in <code>tmp/deploy/sdk/</code>:</p><ul><li><code>poky-glibc-x86_64-core-image-minimal-cortexa9t2hf-neon-toolchain-4.0.sh</code></li></ul><h3 id="step-2-install-sdk-on-developer-workstation" tabindex="-1">Step 2: Install SDK on Developer Workstation <a class="header-anchor" href="#step-2-install-sdk-on-developer-workstation" aria-label="Permalink to &quot;Step 2: Install SDK on Developer Workstation&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Execute self-extracting script</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> poky-glibc-x86_64-core-image-minimal-cortexa9t2hf-neon-toolchain-4.0.sh</span></span></code></pre></div><p><em>(Default installation directory: <code>/opt/poky/4.0</code>)</em></p><h3 id="step-3-compile-code-using-the-sdk" tabindex="-1">Step 3: Compile Code using the SDK <a class="header-anchor" href="#step-3-compile-code-using-the-sdk" aria-label="Permalink to &quot;Step 3: Compile Code using the SDK&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Source environment script to export cross-compiler paths</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/poky/4.0/environment-setup-cortexa9t2hf-neon-poky-linux-gnueabi</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Verify cross-compiler executable</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CC --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Cross-compile your application directly</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CC my_app.c -o my_app</span></span></code></pre></div><hr><h2 id="_3-on-device-package-management-opkg-apt-rpm" tabindex="-1">3. On-Device Package Management (<code>opkg</code>, <code>apt</code>, <code>rpm</code>) <a class="header-anchor" href="#_3-on-device-package-management-opkg-apt-rpm" aria-label="Permalink to &quot;3. On-Device Package Management (\`opkg\`, \`apt\`, \`rpm\`)&quot;">​</a></h2><p>By default, Yocto creates monolithic OS images without on-device package managers. To allow over-the-air package updates (<code>opkg update &amp;&amp; opkg install myapp</code>) directly on deployed target devices:</p><h3 id="step-1-enable-package-management-in-local-conf" tabindex="-1">Step 1: Enable Package Management in <code>local.conf</code> <a class="header-anchor" href="#step-1-enable-package-management-in-local-conf" aria-label="Permalink to &quot;Step 1: Enable Package Management in \`local.conf\`&quot;">​</a></h3><div class="language-bitbake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bitbake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Enable package management feature</span></span>
<span class="line"><span>EXTRA_IMAGE_FEATURES += &quot;package-management&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Select IPK package manager (lightweight Opkg for embedded)</span></span>
<span class="line"><span>PACKAGE_CLASSES = &quot;package_ipk&quot;</span></span></code></pre></div><h3 id="step-2-build-package-repositories-on-host" tabindex="-1">Step 2: Build Package Repositories on Host <a class="header-anchor" href="#step-2-build-package-repositories-on-host" aria-label="Permalink to &quot;Step 2: Build Package Repositories on Host&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package-index</span></span></code></pre></div><p><em>Generates HTTP package feed archives under <code>tmp/deploy/ipk/</code>.</em></p><hr><h2 id="_4-license-compliance-management-in-yocto" tabindex="-1">4. License Compliance Management in Yocto <a class="header-anchor" href="#_4-license-compliance-management-in-yocto" aria-label="Permalink to &quot;4. License Compliance Management in Yocto&quot;">​</a></h2><p>Commercial hardware products must strictly track open-source software licenses (GPLv2, GPLv3, MIT, BSD, Apache-2.0) to prevent legal copyright non-compliance.</p><h3 id="auditing-licenses" tabindex="-1">Auditing Licenses <a class="header-anchor" href="#auditing-licenses" aria-label="Permalink to &quot;Auditing Licenses&quot;">​</a></h3><p>Yocto automatically audits every recipe compiled during build and generates license reports in <code>tmp/deploy/licenses/</code>.</p><h3 id="restricting-non-commercial-or-commercial-restrictive-licenses" tabindex="-1">Restricting Non-Commercial or Commercial-Restrictive Licenses <a class="header-anchor" href="#restricting-non-commercial-or-commercial-restrictive-licenses" aria-label="Permalink to &quot;Restricting Non-Commercial or Commercial-Restrictive Licenses&quot;">​</a></h3><p>To prohibit specific license types (e.g., preventing GPLv3 software in products with locked hardware bootloaders):</p><div class="language-bitbake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bitbake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Blacklist GPLv3 packages from being built</span></span>
<span class="line"><span>INCOMPATIBLE_LICENSE = &quot;GPLv3 GPLv3+&quot;</span></span></code></pre></div><h3 id="accepting-commercial-proprietary-licenses" tabindex="-1">Accepting Commercial/Proprietary Licenses <a class="header-anchor" href="#accepting-commercial-proprietary-licenses" aria-label="Permalink to &quot;Accepting Commercial/Proprietary Licenses&quot;">​</a></h3><p>Some BSP drivers (e.g., VideoCore, Wi-Fi firmware) require explicit acceptance of commercial end-user license agreements (EULA):</p><div class="language-bitbake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bitbake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LICENSE_FLAGS_ACCEPTED = &quot;commercial synaptics&quot;</span></span></code></pre></div>`,38)])])}const m=a(t,[["render",o]]);export{g as __pageData,m as default};
